#if RECAST_ATTACHMENT_PHASE_AUDIT
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Runtime.CompilerServices;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using Spacewars.Runtime;using Spacewars.Simulation;
internal static class RecastAttachmentPhaseAudit {
    static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
    static readonly string[] HNames=Enum.GetNames(typeof(RecastAttachmentPreparation).GetNestedType("Stage",BindingFlags.NonPublic)),FNames=Enum.GetNames(typeof(RecastAttachmentField).GetNestedType("Phase",BindingFlags.NonPublic));
    sealed class H {internal int Id,Phase;internal bool Origin;internal long[] Charges=new long[HNames.Length];internal long FinalWork;internal JToken FinalRoutes;internal List<object> Traces=new();internal Dictionary<string,long> TraceCounts=new();}
    sealed class F {internal int Helper,Side,Phase,Members,Seeds,Capacity,Remaining,Open;internal bool Origin;internal string Surface,Reason;internal long W0,T0,E0,W1,T1,E1;internal object Targets,SeedInputs,Center;internal double Radius;internal long[] Charges=new long[FNames.Length],True=new long[FNames.Length],False=new long[FNames.Length];}
    static readonly ConditionalWeakTable<object,H> HO=new();static readonly ConditionalWeakTable<object,F> FO=new();static readonly List<H> Helpers=new();static readonly List<F> Fields=new();[ThreadStatic]static H current;
    static Dictionary<int,NavPoint> birth;static int checks,native;static long lastTick,readyTick,committed,localWork,refusals;
    internal static string Output{get;private set;}
    static object Point(NavPoint p)=>new{p.X,p.Z};static object Loc(NavLocation p)=>new{Position=Point(p.Position),p.SurfaceId};static object Leg(NavTypedLeg p)=>new{From=Loc(p.From),To=Loc(p.To),p.Cost,Kind=p.Kind.ToString(),p.PortalId};
    static object Route(RecastMemberRoute p)=>p==null?null:new{p.Join,p.Exit,p.OriginLegs,p.TerminalLeg,Spine=p.Spine?.Binding,Waypoints=p.Waypoints.Select(x=>new{Location=Loc(x.Location),x.Height,x.PortalId}).ToArray(),Legs=p.Legs.Select(Leg).ToArray()};
    static object Value(object o,string n)=>o.GetType().GetField(n,Hidden).GetValue(o);
    internal static void Begin(){Output=Environment.GetEnvironmentVariable("RECAST_ATTACHMENT_AUDIT_OUTPUT")??throw new ArgumentException("Unique output required");if(Directory.Exists(Output))throw new ArgumentException("Output exists");Directory.CreateDirectory(Output);}
    internal static void Profile(PlayableProfile p){string hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(WorldWire.Binding(p))).ToLowerInvariant();if(hash!="b5207bb4ceb0cef8dab99434323d266b3a958cd9b81e75d4fff0c9f977fb07e1")throw new InvalidOperationException("Frozen world profile binding changed");}
    internal static void CommandPositions(NavigationSession s,int[] ids){birth=ids.ToDictionary(i=>i,i=>s.Crowd.Units.Single(a=>a.Id==i).Position);}
    internal static void CheckPositions(NavigationSession s,int[] ids,long tick){foreach(int i in ids)if(!s.Crowd.Units.Single(a=>a.Id==i).Position.Equals(birth[i]))throw new InvalidOperationException("EARLY TRANSLATION tick"+tick+" actor"+i);lastTick=tick;checks++;}
    internal static void HelperStep(object o,NavigationRequest[] members,RecastMemberRoute[] baseline,RecastSpineProposal spine,ILayeredNavigationProvider provider){
        if(!HO.TryGetValue(o,out var h)){
            if(members.Length!=49||baseline.Count(x=>x!=null)!=33||spine.Binding!="855d971c0b5bdd81261e7ad69344c352079b374421acf809d4d8bfd923cc5dda"||spine.MapBinding!="33ce3119a22bd95dbd36a09ebd39f922e4b74dede120cdd210201494995b7e3f"||members.Any(q=>q.HeldIdentity!=""||q.Geometry.Revision!=2||q.Profile.Radius!=.58))throw new InvalidOperationException("Frozen original context binding/native baseline changed");
            h=new H{Id=Helpers.Count+1};HO.Add(o,h);Helpers.Add(h);
            var capture=new{Members=members.Select(q=>new{q.Entity,q.Request,Start=Loc(q.StartLocation.Value),Goal=Loc(q.GoalLocation.Value),q.HeldIdentity,Group=q.MemberIdentity?.GroupId,Profile=q.Profile.CaptureWireValues(),q.Profile.ProfileId,q.Profile.Revision,Geometry=new{q.Geometry.Revision,q.Geometry.HalfExtent,Obstacles=q.Geometry.Obstacles.ToArray()}}).ToArray(),Baseline=baseline.Select(Route).ToArray(),Spine=new{spine.Binding,spine.MapBinding,spine.Fan,spine.Stops,spine.FanCenter,spine.FanRadius,Legs=spine.Legs.Select(Leg).ToArray()},ProviderBinding=(provider as PartitionNavigationProvider)?.Binding};
            File.WriteAllText(Path.Combine(Output,"original-context-"+h.Id+".json"),JsonConvert.SerializeObject(capture,Formatting.Indented));
        }current=h;
    }
    internal static void HelperCharge(object o,int phase,int amount,bool origin){var h=HO.GetValue(o,_=>throw new InvalidOperationException("Missing helper"));h.Phase=phase;h.Origin=origin;h.Charges[phase]+=amount;}
    internal static void HelperTrace(int entity,NavLocation a,NavLocation b,bool ok,IReadOnlyList<NavTypedLeg> legs){var h=current??throw new InvalidOperationException("Missing trace context");string key=(h.Origin?"origin/":"terminal/")+HNames[h.Phase]+(ok?"/true":"/false");h.TraceCounts.TryGetValue(key,out long count);h.TraceCounts[key]=count+1;if(HNames[h.Phase]=="PeerScan")h.Traces.Add(new{Entity=entity,Origin=h.Origin,From=Loc(a),To=Loc(b),Complete=ok,Legs=legs?.Select(Leg).ToArray()});}
    internal static void HelperDone(object o,long work){var h=HO.GetValue(o,_=>throw new InvalidOperationException("Missing helper done"));h.FinalWork=work;h.FinalRoutes=JToken.FromObject(((RecastMemberRoute[])Value(o,"WorkingRoutes")).Select(Route).ToArray());}
    internal static void FieldBegin(object o,bool origin,NavPoint center,double radius,int members,int seeds,int capacity,long work,long traces,long expansions,string surface){var f=new F{Helper=(current??throw new InvalidOperationException("Missing field context")).Id,Side=Fields.Count+1,Origin=origin,Center=Point(center),Radius=radius,Members=members,Seeds=seeds,Capacity=capacity,W0=work,T0=traces,E0=expansions,Surface=surface};FO.Remove(o);FO.Add(o,f);Fields.Add(f);}
    internal static void FieldCharge(object o,int phase,int amount){var f=FO.GetValue(o,_=>throw new InvalidOperationException("Missing field"));f.Phase=phase;f.Charges[phase]+=amount;}
    internal static void FieldTrace(object o,bool ok){var f=FO.GetValue(o,_=>throw new InvalidOperationException("Missing field trace"));(ok?f.True:f.False)[f.Phase]++;}
    internal static void FieldEnd(object o,string reason,int remaining,int open,int[] resolved,long work,long traces,long expansions){var f=FO.GetValue(o,_=>throw new InvalidOperationException("Missing field end"));f.Reason=reason;f.Remaining=remaining;f.Open=open;f.W1=work;f.T1=traces;f.E1=expansions;var targets=(NavPoint[])Value(o,"targets");var seeds=(NavPoint[])Value(o,"seeds");var stops=(int[])Value(o,"seedStops");var roots=(int[])Value(o,"roots");f.Targets=Enumerable.Range(0,f.Members).Select(i=>new{Index=i,Position=Point(targets[i]),Resolved=resolved[i]>=0,Node=resolved[i],SourceStop=resolved[i]>=0?stops[roots[resolved[i]]]:-1}).ToArray();f.SeedInputs=Enumerable.Range(0,f.Seeds).Select(i=>new{Index=i,Stop=stops[i],Position=Point(seeds[i])}).ToArray();}
    internal static void Ready(CertifiedRouteKernel k,long tick){readyTick=tick;committed=k.RecastPreparationCommittedWork;native=(int)k.RecastLongQueries;refusals=k.RecastPreparationRefusals;localWork=((RecastGroupPreparation)Value(k,"recastPreparation")).LocalAttachmentWork;if(native!=2)throw new InvalidOperationException("Native query ceiling");}
    static object Counts(string[] names,long[] values)=>names.Select((n,i)=>(n,i)).ToDictionary(x=>x.n,x=>values[x.i]);
    internal static void Finish(){long helper=Helpers.Sum(h=>h.Charges.Sum()),field=Fields.Sum(f=>f.Charges.Sum()),attempted=Helpers.Sum(h=>h.FinalWork);if(helper+field!=attempted||attempted!=localWork||attempted!=committed)throw new InvalidOperationException("Attempted/local/committed phase ledger mismatch");if(Fields.Any(f=>f.Reason==null||f.True.Sum()+f.False.Sum()!=f.T1-f.T0))throw new InvalidOperationException("Incomplete field trace/end transcript");
        var result=new{Result="PASS",Meaning="ONE prep-only source observer; compile-only symbol, no added trace/seed/query or production behavior/default layout/API. No performance/allarrival claim.",CommandPositionsUnchangedEveryTick=true,PositionChecks=checks,LastCheckedTick=lastTick,ReadyTick=readyTick,StopNoExtraAdvance=lastTick==readyTick,NativeQueries=native,CommittedWork=committed,AttemptedWork=attempted,LocalWork=localWork,HelperCharges=helper,FieldCharges=field,Refusals=refusals,Helpers=Helpers.Select(h=>new{h.Id,h.FinalWork,NonFieldCharges=Counts(HNames,h.Charges),h.TraceCounts,ExistingPeerScanTraces=h.Traces,OriginalContext="original-context-"+h.Id+".json",h.FinalRoutes}),Fields=Fields.Select(f=>new{f.Helper,f.Side,f.Origin,f.Surface,f.Center,f.Radius,f.Members,f.Seeds,f.Capacity,EndReason=f.Reason,f.Remaining,f.Open,f.Targets,f.SeedInputs,Charges=Counts(FNames,f.Charges),TrueTraces=Counts(FNames,f.True),FalseTraces=Counts(FNames,f.False),Traces=f.T1-f.T0,Expansions=f.E1-f.E0,WorkAtFieldEnd=f.W1-f.W0,TotalFieldIncludingRouteCopy=f.Charges.Sum()})};File.WriteAllText(Path.Combine(Output,"phase-audit.json"),JsonConvert.SerializeObject(result,Formatting.Indented));Console.WriteLine(JsonConvert.SerializeObject(new{Case="prep-phase-audit",Result="PASS",ReadyTick=readyTick,CommittedWork=committed,HelperCharges=helper,FieldCharges=field,NativeQueries=native}));
    }
}
#endif
